const menu=document.querySelector('.menu'),mobile=document.querySelector('#mobile-nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!open));menu.setAttribute('aria-label',open?'Open menu':'Close menu');menu.textContent=open?'☰':'×';mobile.hidden=open});mobile.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{mobile.hidden=true;menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open menu');menu.textContent='☰'}));
const feelings={overwhelmed:{label:'WHEN EVERYTHING FEELS LIKE TOO MUCH',title:'You don’t have to untangle<br>everything at once.',text:'A place to start: notice what feels heaviest today. You don’t need the perfect words to begin a conversation.',a:'#e3a348',b:'#75b8d3'},disconnected:{label:'WHEN CONNECTION FEELS FAR AWAY',title:'There’s room to find<br>each other again.',text:'A place to start: consider one thing you wish someone understood about you. That can be the beginning of a conversation.',a:'#c94f35',b:'#b6c6a6'},hopeful:{label:'WHEN YOU’RE READY FOR SOMETHING NEW',title:'Small beginnings<br>can hold possibility.',text:'A place to start: imagine what a little more ease might look like in your day. What would you notice first?',a:'#78b8d2',b:'#e7b43e'}};
document.querySelectorAll('[data-feeling]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-feeling]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});const f=feelings[b.dataset.feeling];document.querySelector('#feeling-label').textContent=f.label;document.querySelector('#feeling-title').innerHTML=f.title;document.querySelector('#feeling-text').textContent=f.text;document.querySelector('.shape-a').setAttribute('fill',f.a);document.querySelector('.shape-b').setAttribute('fill',f.b)}));document.querySelectorAll('[data-slide]').forEach(b=>b.addEventListener('click',()=>{const row=document.querySelector('.cards');row.scrollBy({left:Number(b.dataset.slide)*(row.querySelector('article').getBoundingClientRect().width+12),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}));

const consultationDialog=document.querySelector('#consultation-dialog');
document.querySelectorAll('[data-open-consultation]').forEach(button=>button.addEventListener('click',()=>{consultationDialog.showModal();document.body.classList.add('dialog-open')}));
document.querySelector('.dialog-close').addEventListener('click',()=>consultationDialog.close());
consultationDialog.addEventListener('close',()=>document.body.classList.remove('dialog-open'));
consultationDialog.addEventListener('click',event=>{if(event.target!==consultationDialog)return;const box=consultationDialog.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)consultationDialog.close()});
document.querySelector('#consultation-form').addEventListener('submit',event=>event.preventDefault());
